/*!40000 ALTER TABLE `feature_type` DISABLE KEYS */;
INSERT INTO `feature_type` VALUES (5,'background'),(2,'class'),(4,'feat'),(7,'general'),(6,'item'),(1,'racial'),(3,'subclass');
